Host-owned, one writer, synced to desktop and phone: ~/.config/relay/artifacts/<sessionId>/
artifacts.json: {version, items[]}; item = {id ('linear:ENG-6523', 'gh-pr:eCardSystems/react-client-reports-app#238', 'drop:<uuid>', 'url:<normalized>', 'file:<path>', 'experiment:<id>', 'canvas:<slug>', 'branch:<repo>@<name>', 'subagent:<file>'), kind, url | path, title, sources: [messageId], mentions, firstSeen, lastSeen, pinned, pinnedBy ('isaac' | agent id), addedBy ('extractor' | agent id), status: {state, checks, review, fetchedAt}}
tabs.json: {version, tabs[]}; tab = {id, title, icon, createdBy ('default' | agent id), createdAt, rule | items[], order, hidden}
rule = {kind[], state[], caption?, repo?, since?}; items[] = artifact ids.
